from pathlib import Path
from datetime import datetime
import py_compile, shutil

ROOT=Path.cwd(); APP=ROOT/'app'; AC=APP/'access_control.py'; T=APP/'templates'; S=APP/'static'
required=[AC,T/'proposals.html',T/'proposal_new.html',T/'proposal_detail.html',S/'portal.css']
missing=[str(x) for x in required if not x.exists()]
if missing: raise SystemExit('Estrutura incompativel; nada alterado. Faltam: '+', '.join(missing))
text=AC.read_text(encoding='utf-8')
for marker in ['class ProfileProposal(', 'class ProfileProposalAccess(', "@router.get('/portal/propostas'", 'def require_user']:
    if marker not in text: raise SystemExit('Versao incompativel; nada alterado. Marcador ausente: '+marker)
if '# PROPOSAL_UI_V2' in text: raise SystemExit('A melhoria de propostas ja foi aplicada.')
backup=ROOT/f"backup_propostas_{datetime.now():%Y%m%d_%H%M%S}"
for p in required:
    d=backup/p.relative_to(ROOT); d.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(p,d)

routes=r'''

# PROPOSAL_UI_V2 - melhoria isolada do modulo de propostas
def _proposal_or_404(session: Session, proposal_id: int):
    proposal=session.scalar(select(ProfileProposal).options(selectinload(ProfileProposal.department),selectinload(ProfileProposal.accesses).selectinload(ProfileProposalAccess.access)).where(ProfileProposal.id==proposal_id))
    if not proposal: raise HTTPException(404,'Proposta nao encontrada')
    return proposal

def _can_edit_proposal(user: SystemUser, proposal: ProfileProposal):
    return proposal.created_by_id==user.id and proposal.workflow_status in {'RASCUNHO','DEVOLVIDO','REJEITADO'}

def _can_delete_proposal(user: SystemUser, proposal: ProfileProposal):
    return proposal.created_by_id==user.id or (user.role in {ROLE_ADMIN,ROLE_ANALYST} and (not user.department_id or user.department_id==proposal.department_id))

@router.get('/portal/propostas/{proposal_id}/editar',response_class=HTMLResponse)
def proposal_edit(request:Request,proposal_id:int,session:Db,user:Annotated[SystemUser,Depends(require_user)]):
    proposal=_proposal_or_404(session,proposal_id); enforce_department(user,proposal.department_id)
    if not _can_edit_proposal(user,proposal): raise HTTPException(403,'Somente o solicitante pode editar esta proposta neste status')
    accesses=session.scalars(select(Acesso).order_by(Acesso.caminho_completo,Acesso.tela_final,Acesso.botao)).all()
    selected={x.access_id:str(x.status or 'Permitido') for x in proposal.accesses}
    return templates.TemplateResponse(request=request,name='proposal_new.html',context={'user':user,'proposal':proposal,'accesses':accesses,'selected':selected,'edit_mode':True,'employees':[],'profiles':[],'departments':[proposal.department]})

@router.post('/portal/propostas/{proposal_id}/editar')
def proposal_update(proposal_id:int,session:Db,user:Annotated[SystemUser,Depends(require_user)],name:Annotated[str,Form()],description:Annotated[str,Form()]='',justification:Annotated[str,Form()]='',access_ids:Annotated[list[int]|None,Form()]=None):
    proposal=_proposal_or_404(session,proposal_id); enforce_department(user,proposal.department_id)
    if not _can_edit_proposal(user,proposal): raise HTTPException(403,'Proposta nao pode ser editada')
    proposal.name=name.strip(); proposal.description=description.strip() or None; proposal.justification=justification.strip() or None
    proposal.accesses.clear(); session.flush()
    valid=set(session.scalars(select(Acesso.id).where(Acesso.id.in_(access_ids or [-1]))).all())
    proposal.accesses.extend(ProfileProposalAccess(access_id=i,status='Permitido') for i in valid)
    create_history(session,proposal.id,user.id,'PROPOSTA_EDITADA',f'{len(valid)} acessos selecionados')
    session.commit(); return RedirectResponse(f'/portal/propostas/{proposal.id}',303)

@router.post('/portal/propostas/{proposal_id}/excluir')
def proposal_delete(proposal_id:int,session:Db,user:Annotated[SystemUser,Depends(require_user)],reason:Annotated[str,Form()]=''):
    proposal=_proposal_or_404(session,proposal_id); enforce_department(user,proposal.department_id)
    if not _can_delete_proposal(user,proposal): raise HTTPException(403,'Sem permissao para excluir esta proposta')
    if len(reason.strip())<3: raise HTTPException(400,'Informe o motivo da exclusao')
    session.delete(proposal); session.commit(); return RedirectResponse('/portal/propostas',303)
'''
text += routes
AC.write_text(text,encoding='utf-8',newline='\n')

proposals='''<!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/static/portal.css"><title>Propostas</title></head><body>{% include '_portal_nav.html' %}<main><div class="title-row"><div><h1>Propostas de acesso</h1><p class="muted">Crie, acompanhe e revise alterações de acesso.</p></div><a class="primary" href="/portal/propostas/nova">Nova proposta</a></div><div class="proposal-grid">{% for p in proposals %}<article class="proposal-card"><div><span class="status status-{{ p.workflow_status|lower }}">{{ p.workflow_status }}</span><h3><a href="/portal/propostas/{{ p.id }}">{{ p.name }}</a></h3><p>{{ p.department.nome }} · {{ p.origin|replace('_',' ') }}</p></div><div class="proposal-actions"><a href="/portal/propostas/{{ p.id }}">Visualizar</a>{% if p.created_by_id == user.id and p.workflow_status in ['RASCUNHO','DEVOLVIDO','REJEITADO'] %}<a href="/portal/propostas/{{ p.id }}/editar">Editar</a>{% endif %}<button type="button" class="link danger" data-delete="{{ p.id }}" data-name="{{ p.name }}">Excluir</button></div></article>{% else %}<div class="empty-state"><h3>Nenhuma proposta</h3><p>Crie uma proposta para solicitar alterações de acesso.</p></div>{% endfor %}</div></main><dialog id="deleteDialog"><form method="post" id="deleteForm"><h3>Excluir proposta</h3><p id="deleteText"></p><label>Motivo<textarea name="reason" required minlength="3"></textarea></label><div class="dialog-actions"><button type="button" data-close>Cancelar</button><button class="danger-button">Excluir</button></div></form></dialog><script src="/static/proposals.js"></script></body></html>'''
form='''<!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/static/portal.css"><title>{% if edit_mode %}Editar{% else %}Nova{% endif %} proposta</title></head><body>{% include '_portal_nav.html' %}<main><a href="/portal/propostas">Voltar</a><h1>{% if edit_mode %}Editar proposta{% else %}Nova proposta{% endif %}</h1><form class="proposal-form" method="post" action="{% if edit_mode %}/portal/propostas/{{ proposal.id }}/editar{% else %}/portal/propostas/nova{% endif %}"><section class="card proposal-data"><label>Nome<input name="name" required value="{{ proposal.name if proposal else '' }}"></label>{% if not edit_mode %}<label>Departamento<select name="department_id" required>{% for d in departments %}<option value="{{ d.id }}">{{ d.nome }}</option>{% endfor %}</select></label><label>Base<select name="origin" id="origin"><option value="CRIADO_VAZIO">Criar do zero</option><option value="COPIADO_DE_PERFIL">Perfil</option><option value="CONSOLIDADO_FUNCIONARIO">Funcionário</option><option value="CONSOLIDADO_DEPARTAMENTO_COMUM">Comum do departamento</option><option value="CONSOLIDADO_DEPARTAMENTO_UNIAO">União do departamento</option></select></label><label>Perfil base<select name="source_profile_id"><option value="">Selecione</option>{% for p in profiles %}<option value="{{ p.id }}">{{ p.nome }}</option>{% endfor %}</select></label><label>Funcionário base<select name="source_employee_id"><option value="">Selecione</option>{% for e in employees %}<option value="{{ e.id }}">{{ e.nome }}</option>{% endfor %}</select></label>{% endif %}<label>Descrição<textarea name="description">{{ proposal.description if proposal and proposal.description else '' }}</textarea></label><label>Justificativa<textarea name="justification">{{ proposal.justification if proposal and proposal.justification else '' }}</textarea></label></section>{% if edit_mode %}<section class="access-editor"><div class="card tree-pane"><div class="tree-tools"><input id="accessSearch" placeholder="Pesquisar tela ou caminho"><label class="inline"><input type="checkbox" id="onlySelected"> Somente selecionados</label></div><div id="accessTree">{% set ns=namespace(group='') %}{% for a in accesses %}{% if ns.group != a.caminho_completo %}{% if ns.group %}</div></details>{% endif %}<details open class="access-group"><summary><input type="checkbox" class="group-check"> {{ a.caminho_completo }}</summary><div>{% set ns.group=a.caminho_completo %}{% endif %}<label class="access-row" data-search="{{ (a.caminho_completo ~ ' ' ~ a.tela_final ~ ' ' ~ a.botao)|lower }}"><input type="checkbox" name="access_ids" value="{{ a.id }}" data-screen="{{ a.tela_final }}" {% if a.id in selected %}checked{% endif %}><span>{{ a.tela_final }}</span><small>{{ a.botao }}</small></label>{% endfor %}{% if ns.group %}</div></details>{% endif %}</div></div><aside class="card button-pane"><h2 id="screenTitle">Botões da tela</h2><p id="buttonHint">Clique em uma tela na árvore.</p><div id="screenButtons"></div></aside></section>{% else %}<div class="warning">Após criar a proposta, clique em Editar para ajustar telas e botões antes de enviar.</div>{% endif %}<div class="save-bar"><button>{% if edit_mode %}Salvar alterações{% else %}Criar proposta{% endif %}</button></div></form></main><script src="/static/proposals.js"></script></body></html>'''
detail='''<!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/static/portal.css"><title>{{ proposal.name }}</title></head><body>{% include '_portal_nav.html' %}<main><a href="/portal/propostas">Voltar</a><div class="title-row"><div><h1>{{ proposal.name }}</h1><p>{{ proposal.department.nome }} · <span class="status status-{{ proposal.workflow_status|lower }}">{{ proposal.workflow_status }}</span></p></div><div class="proposal-actions">{% if proposal.created_by_id == user.id and proposal.workflow_status in ['RASCUNHO','DEVOLVIDO','REJEITADO'] %}<a class="primary" href="/portal/propostas/{{ proposal.id }}/editar">Editar</a>{% endif %}<button class="link danger" data-delete="{{ proposal.id }}" data-name="{{ proposal.name }}">Excluir</button></div></div><section class="card"><p>{{ proposal.description or '' }}</p><h2>Acessos selecionados ({{ proposal.accesses|length }})</h2><div class="access-list">{% for item in proposal.accesses %}<div><span>{{ item.access.caminho_completo }} › {{ item.access.tela_final }} › {{ item.access.botao }}</span><b class="permission {{ item.status|lower }}">{{ item.status }}</b></div>{% else %}<p>Nenhum acesso selecionado.</p>{% endfor %}</div></section>{% if proposal.workflow_status in ['RASCUNHO','DEVOLVIDO','REJEITADO'] and proposal.created_by_id == user.id %}<form method="post" action="/portal/propostas/{{ proposal.id }}/enviar"><button>Enviar para T.I.</button></form>{% endif %}{% if user.role in ['ADMIN_TI','ANALISTA_TI'] and proposal.workflow_status == 'EM_REVISAO' %}<section class="review">{% for action,label in [('aprovar','Aprovar'),('devolver','Devolver'),('rejeitar','Rejeitar')] %}<form method="post" action="/admin/propostas/{{ proposal.id }}/{{ action }}"><textarea name="details" placeholder="Parecer ou motivo"></textarea><button>{{ label }}</button></form>{% endfor %}</section>{% endif %}</main><dialog id="deleteDialog"><form method="post" id="deleteForm"><h3>Excluir proposta</h3><p id="deleteText"></p><label>Motivo<textarea name="reason" required minlength="3"></textarea></label><div class="dialog-actions"><button type="button" data-close>Cancelar</button><button class="danger-button">Excluir</button></div></form></dialog><script src="/static/proposals.js"></script></body></html>'''
(T/'proposals.html').write_text(proposals,encoding='utf-8')
(T/'proposal_new.html').write_text(form,encoding='utf-8')
(T/'proposal_detail.html').write_text(detail,encoding='utf-8')
js='''document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const d=document.querySelector('#deleteDialog');document.querySelector('#deleteForm').action=`/portal/propostas/${b.dataset.delete}/excluir`;document.querySelector('#deleteText').textContent=`Deseja excluir “${b.dataset.name}”?`;d.showModal()});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());const search=document.querySelector('#accessSearch'),only=document.querySelector('#onlySelected');function filter(){document.querySelectorAll('.access-row').forEach(r=>r.hidden=!(r.dataset.search.includes((search?.value||'').toLowerCase()))||(only?.checked&&!r.querySelector('input').checked))}if(search)search.oninput=filter;if(only)only.onchange=filter;document.querySelectorAll('.group-check').forEach(g=>g.onchange=()=>g.closest('details').querySelectorAll('.access-row input').forEach(x=>x.checked=g.checked));document.querySelectorAll('.access-row').forEach(r=>r.onclick=()=>{const screen=r.querySelector('input').dataset.screen,title=document.querySelector('#screenTitle'),box=document.querySelector('#screenButtons');title.textContent=screen;document.querySelector('#buttonHint').hidden=true;box.innerHTML='';document.querySelectorAll(`.access-row input[data-screen="${CSS.escape(screen)}"]`).forEach(i=>{const l=document.createElement('label');l.className='inline';const c=i.cloneNode();c.onchange=()=>i.checked=c.checked;l.append(c,document.createTextNode(' '+i.closest('label').querySelector('small').textContent));box.append(l)})})'''
(S/'proposals.js').write_text(js,encoding='utf-8')
css='''\n/* PROPOSAL_UI_V2 */.muted{color:#667085}.proposal-grid{display:grid;gap:12px}.proposal-card{background:#fff;border:1px solid #d7e0e8;border-radius:10px;padding:16px;display:flex;justify-content:space-between;gap:15px}.proposal-card h3{margin:8px 0}.proposal-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.link{background:none;color:#1f4e78;padding:4px}.danger{color:#b42318}.danger-button{background:#b42318}.status{display:inline-block;padding:4px 8px;border-radius:999px;background:#e7edf3;font-size:12px}.status-aprovado{background:#dcfae6}.status-rejeitado{background:#fee4e2}.status-em_revisao{background:#fef0c7}.proposal-form{display:grid;gap:14px}.proposal-data{display:grid;grid-template-columns:1fr 1fr;gap:12px}.access-editor{display:grid;grid-template-columns:minmax(430px,1fr) minmax(280px,.55fr);gap:14px}.tree-tools{display:flex;gap:10px;margin-bottom:12px}.tree-tools>input{flex:1}.inline{display:flex!important;align-items:center;gap:6px}.access-group{border-bottom:1px solid #edf0f2;padding:7px}.access-group summary{font-weight:bold;cursor:pointer}.access-row{display:grid!important;grid-template-columns:auto 1fr auto;align-items:center;padding:8px 10px;margin-left:18px;border-bottom:1px solid #f0f2f4;cursor:pointer}.button-pane{align-self:start;position:sticky;top:12px}.button-pane>div{display:grid;gap:10px}.save-bar{position:sticky;bottom:0;background:#fff;border-top:1px solid #d7e0e8;padding:12px;text-align:right}.empty-state{text-align:center;background:#fff;padding:35px;border-radius:10px}dialog{border:0;border-radius:10px;box-shadow:0 18px 50px #0003;width:min(450px,92vw)}dialog label{display:grid;gap:6px}dialog textarea{min-height:85px}.dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}@media(max-width:850px){.access-editor,.proposal-data{grid-template-columns:1fr}.proposal-card{flex-direction:column}}'''
with (S/'portal.css').open('a',encoding='utf-8') as f:f.write(css)
try: py_compile.compile(str(AC),doraise=True)
except Exception:
    for p in required:
        src=backup/p.relative_to(ROOT); shutil.copy2(src,p)
    raise
print('Melhoria da tela de propostas aplicada com sucesso.')
print('Backup:',backup)
print('Arquivos alterados apenas no modulo de propostas e access_control.py.')
